/* the bounds of a window over [from, to) of `len` elements: a list's or an
   array's storage lent as a SpanVal or a view, or a window split in two. */
static void z_coll_window_check(uint64_t _from, uint64_t _to, uint64_t _len, const char* _who);
static void z_coll_window_check(uint64_t _from, uint64_t _to, uint64_t _len, const char* _who) {
    if (_from > _to || _to > _len) {
        char _zp_buf[160];
        snprintf(_zp_buf, sizeof(_zp_buf), "%s: [%lu, %lu) out of bounds (length %lu)", _who, (unsigned long)_from, (unsigned long)_to, (unsigned long)_len);
        z_panic(_zp_buf);
    }
}
static bool z_t81_startsWith(const z_t81_t* self, const z_t81_t* prefix);
static bool z_t81_startsWith(const z_t81_t* self, const z_t81_t* prefix) {
    if (prefix->size > self->size) return false;
    if (prefix->size == 0) return true;
    return memcmp(self->data, prefix->data, prefix->size) == 0;
}

static bool z_t81_endsWith(const z_t81_t* self, const z_t81_t* suffix);
static bool z_t81_endsWith(const z_t81_t* self, const z_t81_t* suffix) {
    if (suffix->size > self->size) return false;
    if (suffix->size == 0) return true;
    return memcmp(self->data + (self->size - suffix->size),
                  suffix->data, suffix->size) == 0;
}

static uint64_t z_t81_indexOf_raw(const z_t81_t* self, const z_t81_t* needle);
static uint64_t z_t81_indexOf_raw(const z_t81_t* self, const z_t81_t* needle) {
    if (needle->size == 0) return 0;
    if (needle->size > self->size) return UINT64_MAX;
    uint64_t last = self->size - needle->size;
    for (uint64_t i = 0; i <= last; i++) {
        if (memcmp(self->data + i, needle->data, needle->size) == 0) {
            return i;
        }
    }
    return UINT64_MAX;
}


static bool z_t81_contains(const z_t81_t* self, const z_t81_t* needle);
static bool z_t81_contains(const z_t81_t* self, const z_t81_t* needle) {
    return z_t81_indexOf_raw(self, needle) != UINT64_MAX;
}

static bool z_ascii_is_ws(unsigned char c);
static bool z_ascii_is_ws(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n'
        || c == '\v' || c == '\f' || c == '\r';
}

static z_t81_t z_t81_substring(const z_t81_t* self, uint64_t from, uint64_t to);
static z_t81_t z_t81_substring(const z_t81_t* self, uint64_t from, uint64_t to) {
    if (from > self->size || to > self->size || from > to) z_panic("substring: bounds error");
    return (z_t81_t){ .size = to - from, .data = self->data + from };
}
